 static volatile PlatformFcmClient activePush;
 @org.springframework.context.annotation.Configuration @org.springframework.context.annotation.Profile("platform-push-test") static class PushProviders {
  @org.springframework.context.annotation.Bean @org.springframework.context.annotation.Primary PlatformPushGateway testGateway(){return new PlatformPushGateway(){public boolean configured(){return activePush!=null&&activePush.configured();}public Result send(String token,UUID notification,String kind,String platform){return activePush==null?new Result("RETRY","PUSH_PROVIDER_NOT_CONFIGURED",null):activePush.send(token,notification,kind,platform);}};}
 }
 static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");
 static ConfigurableApplicationContext context; static JdbcTemplate sql; static String base;
 static ObjectMapper json=new ObjectMapper(); static HttpClient http=HttpClient.newHttpClient();
 record User(UUID id,String token){} record Reply(int status,JsonNode body){}
 @BeforeAll static void start(){postgres.start();context=new SpringApplicationBuilder(MoishowServerApplication.class,PushProviders.class).profiles("db","platform-push-test").run("--server.port=0","--logging.level.root=ERROR","--spring.main.banner-mode=off","--spring.datasource.url="+postgres.getJdbcUrl(),"--spring.datasource.username="+postgres.getUsername(),"--spring.datasource.password="+postgres.getPassword());sql=context.getBean(JdbcTemplate.class);base="http://127.0.0.1:"+((WebServerApplicationContext)context).getWebServer().getPort()+"/api/v1";}
 @AfterAll static void stop(){if(context!=null)context.close();postgres.stop();}
 static User user(){UUID id=UUID.randomUUID();String token=UUID.randomUUID().toString();sql.update("insert into app_user(id,provider,subject,phone,nickname,status) values(?,'GOOGLE',?,?,?,'ACTIVE')",id,id.toString(),"+8210"+String.format("%08d",Math.floorMod(id.hashCode(),100000000)),"사용자");sql.update("insert into service_session(token_hash,user_id,scope,expires_at,revoked) values(?,?,'ACTIVE',now()+interval '1 day',false)",Crypto.hash(token),id);return new User(id,token);}
 static UUID club(User owner,User member){UUID id=UUID.randomUUID();sql.update("insert into club values(?,0,'모임','IMMEDIATE','ACTIVE',?)",id,owner.id);for(User u:List.of(owner,member))sql.update("insert into membership values(?,0,?,?,'닉네임',?,'ACTIVE',false,false)",UUID.randomUUID(),id,u.id,u==owner?"OWNER":"MEMBER");return id;}
 static UUID event(UUID club,User host){UUID id=UUID.randomUUID();sql.update("insert into club_event(id,version,club_id,host_id,responsible_id,title,kind,public_event,starts_at,ends_at) values(?,0,?,?,?,'이벤트','LIGHTNING',true,now(),now()+interval '1 hour')",id,club,host.id,host.id);return id;}
 static Reply call(String method,String path,User u,Object body)throws Exception{var b=HttpRequest.newBuilder(URI.create(base+path)).header("Content-Type","application/json").header("Authorization","Bearer "+u.token).header("Idempotency-Key",UUID.randomUUID().toString());b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));var r=http.send(b.build(),HttpResponse.BodyHandlers.ofString());return new Reply(r.statusCode(),json.readTree(r.body()));}
 @Test void preferencesAndInboxArePrivateAndDurable()throws Exception{var a=user();assertEquals(200,call("GET","/notifications",a,null).status);assertEquals(200,call("POST","/notification-preferences",a,Map.of("pushEnabled",false)).status);assertFalse(call("GET","/notification-preferences",a,null).body.path("pushEnabled").asBoolean(true));assertEquals(403,call("GET","/operator/cases",a,null).status);}
