 @Test void actualFcmHttpAdapterSignsOauthAndPersistsPerDeviceAcceptanceWithoutPrivatePayload()throws Exception{
  var a=user();var keyGenerator=java.security.KeyPairGenerator.getInstance("RSA");keyGenerator.initialize(2048);var pair=keyGenerator.generateKeyPair();
  var server=com.sun.net.httpserver.HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var calls=new java.util.concurrent.ConcurrentHashMap<String,java.util.concurrent.atomic.AtomicInteger>();var payloads=new java.util.concurrent.CopyOnWriteArrayList<JsonNode>();var oauthVerified=new java.util.concurrent.atomic.AtomicBoolean();
  String origin="http://127.0.0.1:"+server.getAddress().getPort();
  server.createContext("/token",exchange->{try{String form=new String(exchange.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);String encoded=Arrays.stream(form.split("&")).filter(part->part.startsWith("assertion=")).findFirst().orElseThrow().substring(10);String assertion=URLDecoder.decode(encoded,java.nio.charset.StandardCharsets.UTF_8);String[] parts=assertion.split("\\.");var signature=java.security.Signature.getInstance("SHA256withRSA");signature.initVerify(pair.getPublic());signature.update((parts[0]+"."+parts[1]).getBytes(java.nio.charset.StandardCharsets.UTF_8));var claims=json.readTree(Base64.getUrlDecoder().decode(parts[1]));oauthVerified.set(signature.verify(Base64.getUrlDecoder().decode(parts[2]))&&claims.path("scope").asText().contains("firebase.messaging"));byte[] body="{\"access_token\":\"local-signed-access\",\"expires_in\":3600,\"token_type\":\"Bearer\"}".getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.getResponseHeaders().add("Content-Type","application/json");exchange.sendResponseHeaders(200,body.length);exchange.getResponseBody().write(body);}catch(Exception error){exchange.sendResponseHeaders(500,-1);}finally{exchange.close();}});
  server.createContext("/v1/projects/local-project/messages:send",exchange->{try{if(!"Bearer local-signed-access".equals(exchange.getRequestHeaders().getFirst("Authorization")))throw new IllegalStateException("oauth missing");var body=json.readTree(exchange.getRequestBody().readAllBytes());payloads.add(body);String token=body.path("message").path("token").asText();int attempt=calls.computeIfAbsent(token,key->new java.util.concurrent.atomic.AtomicInteger()).incrementAndGet();int status=token.equals("expired-device-token")?404:token.equals("retry-device-token")&&attempt==1?503:200;String result=status==200?"{\"name\":\"projects/local-project/messages/"+token+"\"}":status==404?"{\"error\":{\"details\":[{\"errorCode\":\"UNREGISTERED\"}]}}":"{\"error\":{\"status\":\"UNAVAILABLE\"}}";byte[] bytes=result.getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.getResponseHeaders().add("Content-Type","application/json");exchange.sendResponseHeaders(status,bytes.length);exchange.getResponseBody().write(bytes);}catch(Exception error){exchange.sendResponseHeaders(500,-1);}finally{exchange.close();}});
  server.start();var credentials=java.nio.file.Files.createTempFile("moishow-fcm-contract-",".json");
  try{String privateKey="-----BEGIN PRIVATE KEY-----\n"+Base64.getMimeEncoder(64,new byte[]{10}).encodeToString(pair.getPrivate().getEncoded())+"\n-----END PRIVATE KEY-----\n";java.nio.file.Files.writeString(credentials,json.writeValueAsString(Map.of("type","service_account","project_id","local-project","private_key_id","local-test-key","private_key",privateKey,"client_email","local@local-project.iam.gserviceaccount.com","client_id","123456","token_uri",origin+"/token")));
   activePush=new PlatformFcmClient(json,"local-project",credentials.toString(),URI.create(origin));
   for(String token:List.of("good-device-token","retry-device-token","expired-device-token"))assertEquals(200,call("POST","/push/devices",a,Map.of("token",token,"platform","ANDROID")).status);
   platform().notify(a.id,"MONEY",null,null,"송금 캡처와 비공개 소명 원문");platform().tick();assertTrue(oauthVerified.get(),"official SDK must sign a scoped OAuth assertion");assertEquals("RETRY",sql.queryForObject("select o.status from platform_outbox o join platform_notification n on n.id=o.notification_id where n.user_id=?",String.class,a.id));
   sql.update("update platform_outbox set next_attempt_at=now() where notification_id in(select id from platform_notification where user_id=?)",a.id);platform().tick();assertEquals("SENT",sql.queryForObject("select o.status from platform_outbox o join platform_notification n on n.id=o.notification_id where n.user_id=?",String.class,a.id));assertEquals(1,calls.get("good-device-token").get());assertEquals(2,calls.get("retry-device-token").get());assertEquals(1,calls.get("expired-device-token").get());assertEquals(2,call("GET","/push/devices",a,null).body.size());assertEquals(1,call("GET","/notifications",a,null).body.size());for(var payload:payloads){assertFalse(payload.toString().contains("송금 캡처"));assertFalse(payload.path("message").path("data").path("notificationId").asText().isBlank());}
  }finally{activePush=null;server.stop(0);java.nio.file.Files.deleteIfExists(credentials);}
 }

