 @Test void financialDisputeDelegationIsExactAndPublicResultsNeverContainPrivateProof()throws Exception{
  var owner=user();var member=user();var other=user();var operator=user();var secondOperator=user();var club=club(owner,member);addMember(club,other);var event=event(club,owner);participant(event,member);UUID book=UUID.randomUUID(),dispute=UUID.randomUUID(),otherDispute=UUID.randomUUID();sql.update("insert into settlement_book(id,version,event_id,status,mode) values(?,0,?,'OPEN','POSTPAY')",book,event);
  for(UUID id:List.of(dispute,otherDispute))sql.update("insert into finance_dispute(id,version,book_id,user_id,status,reason,evidence,public_result,correction_amount,created_at) values(?,0,?,?,'REVIEWING','비공개 이의 사유','PRIVATE_TRANSFER_CAPTURE','진행 결과 공개',0,now())",id,book,id.equals(dispute)?member.id:other.id);for(var op:List.of(operator,secondOperator))sql.update("insert into platform_operator(user_id,provisioned_by) values(?,?)",op.id,"offline-dispute-review");
  assertEquals(403,call("POST","/support/requests",other,Map.of("eventId",event,"financialDisputeId",dispute,"reason","타인 건 위조")).status);var requested=call("POST","/support/requests",member,Map.of("eventId",event,"financialDisputeId",dispute,"reason","본인 이의 무응답"));assertEquals(200,requested.status,requested.body.toString());String id=requested.body.path("id").asText();String privatePath="/events/"+event+"/finance/disputes/"+dispute;
  assertEquals(403,call("GET",privatePath,operator,null).status);assertEquals(200,call("POST","/support/cases/"+id+"/claim",operator,Map.of("version",0)).status);var detail=call("GET",privatePath,operator,null);assertEquals(200,detail.status,detail.body.toString());assertTrue(detail.body.toString().contains("PRIVATE_TRANSFER_CAPTURE"));assertEquals(403,call("GET",privatePath,secondOperator,null).status);assertEquals(403,call("GET","/events/"+event+"/finance/disputes/"+otherDispute,operator,null).status);assertEquals(403,call("GET","/events/"+event+"/finance",operator,null).status);
  var publicResult=call("GET","/events/"+event+"/support/results",other,null);assertEquals(200,publicResult.status,publicResult.body.toString());assertTrue(publicResult.body.toString().contains("진행 결과 공개"));assertFalse(publicResult.body.toString().contains("PRIVATE_TRANSFER_CAPTURE"));assertFalse(publicResult.body.toString().contains("비공개 이의 사유"));assertEquals(200,call("POST","/support/cases/"+id+"/decisions",operator,Map.of("version",1,"action","RESOLVE","reason","운영 응답 종료 기록")).status);assertEquals(200,call("GET",privatePath,operator,null).status);assertEquals(403,call("POST","/events/"+event+"/finance/disputes/"+dispute+"/resolve",operator,Map.of("version",0,"status","REJECTED","reason","종료 사건 권한으로 재처리 금지")).status);sql.update("delete from platform_operator where user_id=?",operator.id);assertEquals(403,call("GET",privatePath,operator,null).status);
 }
